% 1. Student Marks Matrix
marks = [
    75 80 85;
    60 65 70;
    90 88 95;
    55 60 58;
    80 85 82;
    70 72 75;
    65 68 70;
    85 90 88;
    50 55 60;
    95 92 98
    ];
attendence = [85 70 95 60 90 80 65 92 55 98];
% Calculate Total and Average Marks
totalMarks = sum(marks, 2);
averageMarks = mean(marks, 2);
disp('Student Average Marks:'); %[output:1481ab64]
disp(averageMarks); %[output:238aaf51]
% 2. Statistical Calculations
disp('Mean:'); %[output:7e9e9832]
disp(mean(averageMarks)); %[output:7024d27d]
disp('Median:'); %[output:117ddd4f]
disp(median(averageMarks)); %[output:246bad81]
disp('Mode:'); %[output:0bf3084a]
disp(mode(averageMarks)); %[output:59154d28]
disp('Range:'); %[output:14f1dc13]
disp(range(averageMarks)); %[output:70fbe3e0]
disp('Range:'); %[output:10c43016]
disp(range(averageMarks)); %[output:4f4a7daa]
disp('Variance:'); %[output:7e37b5d3]
disp(var(averageMarks)); %[output:63b678bb]
disp('Standard Deviation:'); %[output:5e9b600f]
disp(std(averageMarks)); %[output:1932c84b]
% 3. Correlation between Attendance and Marks
correlation = corrcoef(attendence, averageMarks);
disp('Correlation:'); %[output:5ce2ebab]
disp(correlation(1,2)); %[output:7747d945]

figure; %[output:8506c8a7]
scatter(attendence, averageMarks, 'filled'); %[output:8506c8a7]
xlabel('Attendence (%)'); %[output:8506c8a7]
ylabel('Average Marks'); %[output:8506c8a7]
title('Attendence vs Student Performance'); %[output:8506c8a7]
grid on; %[output:8506c8a7]

% 4. Linear Regression

p = polyfit(attendence, averageMarks, 1);

predictedMarks = polyval(p, attendence);

disp('Predicted Marks:'); %[output:6840025a]
disp(predictedMarks); %[output:8af89f6c]

figure; %[output:334d1d03]
scatter(attendence, averageMarks, 'filled'); %[output:334d1d03]
hold on; %[output:334d1d03]

plot(attendence, predictedMarks, 'r', 'LineWidth', 2); %[output:334d1d03]

xlabel('Attendence (%)'); %[output:334d1d03]
ylabel('Average Marks'); %[output:334d1d03]
title('Linear Regression'); %[output:334d1d03]

legend('Actual Marks', 'Predicted Marks'); %[output:334d1d03]
grid on; %[output:334d1d03]
hold off; %[output:334d1d03]

% 5. T-Test: Compare Two Student Groups
group1 = averageMarks(1:5);
group2 = averageMarks(6:10);

[h, pValue] = ttest2(group1, group2);

disp('T-Test Result:'); %[output:4cccab6e]
disp(h); %[output:3379624d]

disp('P-Value:'); %[output:0cb4fbf5]
disp(pValue); %[output:0ee753b1]

if h == 1 %[output:group:51742175]
    disp('Significant difference between groups.');
else
    disp('No significant difference between groups.'); %[output:969a3e85]
end %[output:group:51742175]

% 6. Performance Report
disp('===== STUDENT PERFORMANCE REPORT ====='); %[output:6ee39863]

disp(['Class Average: ', num2str(mean(averageMarks))]); %[output:11827ba9]

disp(['Highest Marks: ', num2str(max(averageMarks))]); %[output:8cbc0fb4]

disp(['Lowest Marks: ', num2str(min(averageMarks))]); %[output:293e6e6d]

disp(['Average Attendance: ', num2str(mean(attendence))]); %[output:76312872]

disp('Project Completed Successfully!'); %[output:4d3f57ba]






